  'Сюда попадает всё, что разобрал помощник: числа из письма, файла или скриншота. Ничего не применяется само — вы смотрите строки и решаете по каждой.':
    'Мұнда көмекші талдағанның бәрі түседі: хаттан, файлдан немесе скриншоттан алынған сандар. Ештеңе өздігінен қолданылмайды — жолдарды қарап, әрқайсысы бойынша өзіңіз шешесіз.',
  'Сюда попадают раунды подачи ваших учеников на ближайшие 120 дней. Дедлайн живёт у вуза: заведите раунды в справочнике — и они появятся здесь, а заодно превратятся в задачи учеников.':
    'Мұнда оқушыларыңыздың алдағы 120 күндегі өтінім раундтары түседі. Дедлайн ЖОО-да тұрады: раундтарды анықтамалықта ашыңыз — олар осында пайда болады әрі оқушылардың тапсырмаларына айналады.',
