  'Сначала откройте карточку ученика или отметьте одного в таблице.':
    'Алдымен оқушының карточкасын ашыңыз немесе кестеде біреуін белгілеңіз.',
  'Ближайшие раунды подачи ваших учеников. Дедлайн принадлежит вузу: сдвиньте его в справочнике — он сдвинется у всех.':
    'Оқушыларыңыздың жақындағы өтініш раундтары. Мерзім университетке тиесілі: анықтамалықта өзгертсеңіз, ол барлығында өзгереді.',
  'Ближайшие старты и сколько учеников на них заявлено.':
    'Жақындағы жарыстар және оларға қанша оқушы тіркелген.',
  'Заполненность профилей и зона риска по каждой учебной группе.':
    'Әр оқу тобы бойынша профильдердің толтырылуы және тәуекел аймағы.',
  'Кандидаты, у которых баллы уже открывают сильные программы.':
    'Балдары күшті бағдарламаларды ашып тұрған үміткерлер.',
