    'Дәл қазір бақылау қажет оқушылар. Бұл белгілер тек қызметкерлерге көрінеді.',
  'Моки на платформе и те, у кого балл просел с прошлой попытки.':
    'Платформадағы сынақтар және өткен әрекеттен бері балы төмендегендер.',
  'Учебных групп пока нет.': 'Әзірге оқу топтары жоқ.',
  'Худшие домашние работы': 'Ең нашар үй жұмыстары',
  'Чем ученик усиливает заявку. Без основного трека портфолио собирается вслепую.':
    'Оқушы өтінімін немен күшейтеді. Негізгі трексіз портфолио соқыр жиналады.',
  'ближайших стартов в календаре': 'күнтізбедегі жақындағы жарыстар',
  'заполненность профилей по группам': 'топтар бойынша профильдердің толтырылуы',
  'кандидаты на IELTS 7.5+ и SAT 1500+': 'IELTS 7.5+ және SAT 1500+ үміткерлері',
