  'Очистка истории загрузок': 'Жүктеу тарихын тазалау',
  'Пароли показываются один раз: в базе хранится только их отпечаток. Скачайте список, если письма не уходят, — потом восстановить их будет нельзя, только выпустить новые.':
    'Құпиясөздер бір рет көрсетіледі: базада тек олардың ізі сақталады. Хаттар жіберілмесе, тізімді жүктеп алыңыз — кейін оларды қалпына келтіру мүмкін емес, тек жаңасын беруге болады.',
  'По домену модель ищет требования на официальном сайте — без него сверка не работает.':
    'Модель талаптарды осы домен бойынша ресми сайттан іздейді — онсыз салыстыру жұмыс істемейді.',
  'Показать неактивных': 'Белсенді еместерді көрсету',
  'Пустое поле значит «требования нет», а не ноль: по незаполненному порогу проходят все.':
    'Бос өріс «талап жоқ» дегенді білдіреді, нөл емес: толтырылмаған табалдырықтан бәрі өтеді.',
