  'Балл с сертификата: дата и секции. Значение сразу настоящее — очереди нет. Пробники вносятся файлом на экране «Пробники», руками здесь не правятся.': 'Сертификаттағы балл: күні мен секциялары. Мән бірден нақты — кезек жоқ. Сынақтар «Сынақтар» экранында файлмен енгізіледі, мұнда қолмен өзгертілмейді.',
  'Ваше предложение закрыто, отклонения нет.': 'Ұсынысыңыз жабылды, бас тарту жоқ.',
  'Внести балл': 'Балл енгізу',
  'Два пути: ученик вносит балл — вы подтверждаете; или вносите сами — значение сразу настоящее. Пробники загружаются файлом от учителя и руками не правятся.': 'Екі жол: оқушы балл енгізеді — сіз растайсыз; немесе өзіңіз енгізесіз — мән бірден нақты. Сынақтар мұғалімнің файлымен жүктеледі және қолмен өзгертілмейді.',
  'Два пути: ученик загружает файл — вы подтверждаете; или загружаете сами — документ сразу подтверждён. Файлы открываются только после входа, прямых ссылок нет.': 'Екі жол: оқушы файл жүктейді — сіз растайсыз; немесе өзіңіз жүктейсіз — құжат бірден расталған. Файлдар тек кіргеннен кейін ашылады, тікелей сілтемелер жоқ.',
