  'Подбор показывает соответствие требованиям вуза. Раунд подачи и статус заявки ведёт директор по поступлению.': 'Іріктеу ЖОО талаптарына сәйкестікті көрсетеді. Тапсыру раунды мен өтінім мәртебесін түсу жөніндегі директор жүргізеді.',
  'Поставить цель': 'Мақсат қою',
  'Программы, которые добавил ученик или вы, можно менять и убирать. Строку, которую завела Асем, снимает она.': 'Оқушы немесе сіз қосқан бағдарламаларды өзгертуге және алып тастауға болады. Асем енгізген жолды өзі алып тастайды.',
