  'Ученик предлагает — директора талантов и спорта подтверждают; или вносите сами, сразу': 'Оқушы ұсынады — таланттар мен спорт директорлары растайды; немесе өзіңіз бірден енгізесіз',
  'Файл документа': 'Құжат файлы',
  'Файл → что заполняем → проверка → готово. Пишутся только ваши группы: лист чужой группы — ошибка листа.': 'Файл → нені толтырамыз → тексеру → дайын. Тек сіздің топтарыңыз жазылады: бөтен топтың парағы — парақ қатесі.',
