  'Группы ещё не играли — сыграйте первым.': 'Топтар әлі ойнаған жоқ — бірінші болып ойнаңыз.',
  'Здесь только суммы групп: строк отдельных учеников в этом зачёте нет.': 'Мұнда тек топтардың қосындысы: жеке оқушылардың жолдары бұл есепте жоқ.',
  'Соло на время, вызов однокласснику по коду и зачёт групп. Личных рейтингов у нас нет.': 'Уақытқа соло, сыныптасқа код арқылы шақыру және топтар есебі. Жеке рейтингтер бізде жоқ.',
  'Кто учится, в какой группе и с какой почтой.': 'Кім оқиды, қай топта және қандай поштамен.',
  'Кто учится и в какой группе. Доменные поля ведут директора у себя.': 'Кім оқиды және қай топта. Домен өрістерін директорлар өздері жүргізеді.',
  'Имя, группа, почта и год выпуска. Доменные данные — баллы, посещаемость, портфолио — ведут директора у себя, здесь их нет.': 'Аты, тобы, поштасы және бітіру жылы. Домен деректерін — балдар, қатысу, портфолио — директорлар өздері жүргізеді, мұнда олар жоқ.',
  'Шаблон превращается в задачу при генерации роадмапа: срок берётся из дня и месяца, а «кому» сужает его до выбранных групп.': 'Үлгі роадмап жасалғанда тапсырмаға айналады: мерзім күн мен айдан алынады, ал «кімге» оны таңдалған топтарға дейін тарылтады.',
  'Выберите из списка или введите своё': 'Тізімнен таңдаңыз немесе өзіңіздікін енгізіңіз',
  '«+» — был, «н» — не был, серая клетка — выходной, «—» — ученика в этот день не отмечали.': '«+» — болды, «н» — болмады, сұр ұяшық — демалыс, «—» — оқушы бұл күні белгіленбеген.',
