  'Один журнал — один предмет у одного состава: группы, подгруппы или потока. Слева ученики, по верху уроки, в каждом уроке посещаемость и оценка рядом.': 'Бір журнал — бір құрамдағы бір пән: топ, топша немесе ағын. Сол жақта оқушылар, жоғарыда сабақтар, әр сабақта қатысу мен баға қатар.',
