  'Откройте урок и отметьте только тех, кого нет. Остальные считаются присутствующими. Оценку можно поставить сразу в строке ученика. Неотмеченный урок напомнит о себе через 10 минут после звонка.': 'Сабақты ашып, тек жоқтарды белгілеңіз. Қалғандары қатысқан болып саналады. Бағаны оқушының жолында бірден қоюға болады. Белгіленбеген сабақ қоңыраудан 10 минуттан кейін еске салады.',
