  'Подгруппа стоит в расписании: удалить нельзя, пока есть её уроки.': 'Топша кестеде тұр: сабақтары бар кезде жоюға болмайды.',
  'Подгруппа удалена': 'Топша жойылды',
  'Подгруппа — часть группы для одного предмета: английский по уровню, информатика пополам. Две подгруппы идут в одно время в разных кабинетах. Поток — несколько групп или подгрупп на одном уроке. Ученик переходит в другую подгруппу с даты: старые оценки остаются в прежнем журнале, новые идут в новый.': 'Топша — бір пән үшін топтың бөлігі: ағылшын деңгей бойынша, информатика екіге. Екі топша бір уақытта әртүрлі кабинетте оқиды. Ағын — бір сабақтағы бірнеше топ немесе топша. Оқушы басқа топшаға күннен бастап ауысады: ескі бағалар бұрынғы журналда қалады, жаңалары жаңасына жазылады.',
  'Подгруппы': 'Топшалар',
  'Подгруппы и потоки': 'Топшалар мен ағындар',
  'Пока СОЧ не было, вес делится между ФО и СОР.': 'ТЖБ болмағанша, салмақ ҚБ мен БЖБ арасында бөлінеді.',
