  'Посещаемость и оценки ставит учитель урока или заменяющий. Уважительную причину за период оформляет куратор.': 'Қатысу мен бағаларды сабақ мұғалімі немесе алмастырушы қояды. Кезеңге дәлелді себепті куратор рәсімдейді.',
