  'Расписание ведут Кымбат и администратор. Если урок стоит неудобно, попросите перенос — просьба уйдёт Кымбат.': 'Кестені Кымбат пен әкімші жүргізеді. Сабақ ыңғайсыз тұрса, ауыстыруды сұраңыз — өтініш Кымбатқа кетеді.',
