  'Теперь заведите уроки для подгрупп в расписании': 'Енді топшаларға сабақтарды кестеде енгізіңіз',
  'Только свои уроки и учеников своих составов: оценки и пропуски по вашим предметам, группу и куратора. Заметки кураторов, документы и поступление вам не видны.': 'Тек өз сабақтарыңыз бен құрамдарыңыздың оқушылары: өз пәндеріңіз бойынша бағалар мен босатулар, топ және куратор. Кураторлардың жазбалары, құжаттар және түсу сізге көрінбейді.',
  'Только этот урок': 'Тек осы сабақ',
