  'У группы по этому предмету уже есть подгруппы. Новое деление заменит их с выбранной даты, старые журналы сохранятся.': 'Топта осы пән бойынша топшалар бар. Жаңа бөлу оларды таңдалған күннен бастап алмастырады, ескі журналдар сақталады.',
