  'Урок ещё впереди: отметить можно со звонка. Тему и домашнее задание можно записать заранее.': 'Сабақ әлі алда: қоңыраудан бастап белгілеуге болады. Тақырып пен үй тапсырмасын алдын ала жазуға болады.',
  'Урок заводится один раз и повторяется по неделям': 'Сабақ бір рет енгізіліп, апта сайын қайталанады',
