  'Уроки ваших групп по дням, подгруппы рядом, замены и отмены. Нажмите на урок — увидите, кто отсутствовал.': 'Топтарыңыздың сабақтары күндер бойынша, топшалар қатар, алмастырулар мен күшін жоюлар. Сабақты басыңыз — кім болмағанын көресіз.',
