  'Ученик — свои. Куратор группы, Кымбат и администратор — все. Родители — в отчёте раз в месяц.': 'Оқушы — өзінікін. Топ кураторы, Кымбат және әкімші — барлығын. Ата-аналар — айына бір рет есепте.',
  'Ученики увидят в расписании': 'Оқушылар кестеде көреді',
  'Учителей': 'Мұғалімдер',
  'Учитель': 'Мұғалім',
  'Учитель видит только свои уроки и учеников своих составов. На уроке отмечает отсутствующих и ставит ФО, СОР и СОЧ. Через 10 минут после звонка неотмеченный урок напоминает о себе в колокольчик.': 'Мұғалім тек өз сабақтары мен құрамдарының оқушыларын көреді. Сабақта жоқтарды белгілеп, ҚБ, БЖБ және ТЖБ қояды. Қоңыраудан 10 минуттан кейін белгіленбеген сабақ қоңыраушаға еске салады.',
