  'Балл с сертификата или балл пробника: дата и секции. Значение сразу настоящее — очереди нет. Текущий балл ученика пишут только официальные попытки. Пробник из файла Кымбат здесь не правится.': 'Сертификаттағы балл немесе сынама балы: күні мен бөлімдері. Мән бірден нақты — кезек жоқ. Оқушының ағымдағы балын тек ресми талпыныстар жазады. Кымбат файлынан келген сынама мұнда түзетілмейді.',
