  'Ваши уроки по дням со своей подгруппой и потоком, замены и отмены, СОР и СОЧ. Нажмите на урок — увидите тему, домашнее задание и свою отметку.': 'Күндер бойынша сабақтарыңыз өз топшаңызбен және ағыныңызбен, ауыстырулар мен күшін жоюлар, БЖБ мен ТЖБ. Сабақты басыңыз — тақырыпты, үй тапсырмасын және өз белгіңізді көресіз.',
