  'Из дедлайнов ваших вузов, из плана по каждой программе и от директоров. Выполненную задачу закрываете вы; на проверку уходит то, что подтверждает школа.': 'Университеттеріңіздің мерзімдерінен, әр бағдарлама жоспарынан және директорлардан. Орындалған тапсырманы сіз жабасыз; мектеп растайтыны тексеруге кетеді.',
  'Избранное — заметки на полях: программу присмотрели, но ещё не решили. В список подачи она попадает кнопкой «В мой список», и тогда её дедлайн становится задачей плана.': 'Таңдаулылар — шеттегі жазбалар: бағдарламаны байқадыңыз, бірақ әлі шешкен жоқсыз. Өтінім тізіміне ол «Менің тізіміме» түймесімен түседі, сонда оның мерзімі жоспар тапсырмасына айналады.',
