  'Программы, которые добавили вы, можно менять и убирать. Строку, которую завела Асем, снимает она. Приоритетный вуз — один на список, он идёт первым.': 'Өзіңіз қосқан бағдарламаларды өзгертуге және алып тастауға болады. Асем енгізген жолды өзі алады. Басым университет — тізімге біреу, ол бірінші тұрады.',
  'Пропущенный шаг всегда можно вернуть': 'Өткізілген қадамды әрқашан қайтаруға болады',
