  'Шаги считаются по данным: внесли баллы — шаг закрыт сам. Пропуск — только отложить: он не меняет ничего в данных.': 'Қадамдар деректер бойынша есептеледі: балл енгіздіңіз — қадам өзі жабылды. Өткізу — тек кейінге қалдыру: ол деректерде ештеңе өзгертпейді.',
  'Шесть вопросов на время: точность весит больше скорости. Можно одному, можно позвать одноклассника по коду. Личных рейтингов нет.': 'Уақытқа алты сұрақ: дәлдік жылдамдықтан салмақтырақ. Жалғыз да, кодпен сыныптасты шақырып та болады. Жеке рейтингтер жоқ.',
  'Школьный аккаунт после выпуска отключат. Личную почту можно привязать на главной.': 'Мектеп аккаунты бітіргеннен кейін өшіріледі. Жеке поштаны басты бетте байланыстыруға болады.',
