  '«у» снижает процент, но в риск не входит; в риск идут только «н». День без причины — не меньше двух «н» и 60 % уроков дня.': '«у» пайызды төмендетеді, бірақ тәуекелге кірмейді; тәуекелге тек «н» кіреді. Себепсіз күн — кемінде екі «н» және күн сабақтарының 60 %.',
