  'Мера берётся из закрытого набора действий: за балл IELTS или GPA бейдж завести нельзя. Порог правится в строке, новый бейдж заводится без выката. Рейтингов и сравнения с другими учениками у ученика нет.': 'Өлшем жабық әрекеттер жиынынан алынады: IELTS немесе GPA балы үшін бейдж енгізуге болмайды. Шек жолда түзетіледі, жаңа бейдж шығарусыз енгізіледі. Оқушыда рейтинг пен басқалармен салыстыру жоқ.',
