  'Показывается, когда': 'Қашан көрсетіледі',
  'Порог читается по условию: проценты у посещаемости, дни у входа, баллы у пробных. Список собирается из пропусков, моков, активности и дедлайнов.': 'Шек шарт бойынша оқылады: қатысуда пайыз, кіруде күн, сынақта балл. Тізім босатулар, сынақтар, белсенділік пен мерзімдерден жиналады.',
