  'Стартовый справочник — 20 вузов, куда обычно поступают выпускники; все его записи придут с плашкой «не подтверждено». Файл требований загружает администратор, подтверждает записи директор по поступлению.': 'Бастапқы анықтамалық — түлектер әдетте түсетін 20 университет; барлық жазбалары «расталмаған» белгісімен келеді. Талаптар файлын әкімші жүктейді, жазбаларды түсу жөніндегі директор растайды.',
