  'Тексты ведёт администратор: на одну просьбу — одно письмо. Директора и кураторы берут шаблон в диалоге письма и подставляют переменные руками.': 'Мәтіндерді әкімші жүргізеді: бір өтінішке — бір хат. Директорлар мен кураторлар үлгіні хат диалогынан алып, айнымалыларды қолмен қояды.',
  'Тип': 'Түрі',
  'Тип записи': 'Жазба түрі',
  'Уважительную причину за период оформляет куратор на экране посещаемости; звонок родителям — по правилам обзвона.': 'Кезеңге дәлелді себепті куратор қатысу экранында рәсімдейді; ата-анаға қоңырау — қоңырау ережелері бойынша.',
