  'Уйдёт удалений': 'Жойылулар кетеді',
  'Условие берётся из закрытого набора: считать его должен код, а не текст. Пока условие не выполнено, сюжет ученику не показывается; порядок задаёт очередь подсказок.': 'Шарт жабық жиыннан алынады: оны мәтін емес, код есептеуі керек. Шарт орындалмайынша сюжет оқушыға көрсетілмейді; реті кеңестер кезегін белгілейді.',
  'Ученики, учётные записи, вузы из их списков, задачи, эссе и удалённые уроки с отметками. Запись возвращается вместе со всем, что ушло с ней; стирание навсегда оставляет только журнал изменений.': 'Оқушылар, тіркелгілер, тізімдеріндегі университеттер, тапсырмалар, эссе және белгілері бар жойылған сабақтар. Жазба өзімен кеткеннің бәрімен қайтады; біржола өшіру тек өзгерістер журналын қалдырады.',
