  'Файл с колонками: ФИО, группа и почта, если она есть. Ученику без почты заведётся логин «имя.фамилия». Группа должна быть заведена заранее: с ней приходит параллель. Из каждой строки появятся карточка ученика, учётная запись и временный пароль.': 'Бағандары бар файл: аты-жөні, топ және пошта, егер бар болса. Поштасы жоқ оқушыға «аты.тегі» логині ашылады. Топ алдын ала ашылуы керек: параллель онымен келеді. Әр жолдан оқушы карточкасы, тіркелгі және уақытша құпиясөз пайда болады.',
