  'Импорт меняет только учителя на куратора и обратно. Остальное — руками в «Пользователях».': 'Импорт тек мұғалімді кураторға және керісінше ауыстырады. Қалғаны — «Пайдаланушылар» бөлімінде қолмен.',
  'Импорт расписания': 'Кестені импорттау',
  'Книга школы с листами «Сотрудники», «Группы», «Предметы», «Звонки», «Подгруппы», «Уроки». Сначала предпросмотр: база не меняется, пока не нажата «Применить». Повторный импорт того же файла ничего не удваивает.': '«Сотрудники», «Группы», «Предметы», «Звонки», «Подгруппы», «Уроки» парақтары бар мектеп кітабы. Алдымен алдын ала қарау: «Қолдану» басылмайынша база өзгермейді. Сол файлды қайта импорттау ештеңені қайталамайды.',
  'Кто ведёт этот урок': 'Бұл сабақты кім жүргізеді',
  'Обновится': 'Жаңартылады',
  'Ошибки — импорт не пойдёт, пока их не исправить в файле': 'Қателер — файлда түзетілмейінше импорт жүрмейді',
  'Пароли показываются один раз и скачиваются списком один раз: в базе только их отпечаток. Срок временного пароля — 48 часов.': 'Құпиясөздер бір рет көрсетіледі және тізіммен бір рет жүктеледі: базада тек олардың ізі бар. Уақытша құпиясөз мерзімі — 48 сағат.',
  'Предупреждения': 'Ескертулер',
  'Применяется…': 'Қолданылуда…',
  'Роль не меняется': 'Рөл өзгермейді',
  'Смена куратора': 'Кураторды ауыстыру',
  'Создастся': 'Ашылады',
  'Список скачан': 'Тізім жүктелді',
  'Уроки в LMS, которых нет в файле': 'LMS-тегі файлда жоқ сабақтар',
  'Учитель не назначен': 'Мұғалім тағайындалмаған',
  'Учётки заводятся выключенными и без пароля. Права администратора импорт не даёт никогда — роль и доступ назначаются в «Пользователях».': 'Тіркелгілер өшірулі және құпиясөзсіз ашылады. Импорт әкімші құқығын ешқашан бермейді — рөл мен кіру «Пайдаланушылар» бөлімінде беріледі.',
